/* Original photoreal vehicle concept sprites, generated for Street r0d (no external trademarks/assets).
 * 6 body-class templates. Existing game rules remain server-authoritative. */
const PHOTO_DATA = Object.freeze({
  'coupe':'',
  'hardtop':'',
  'muscle':'',
  'wagon':'',
  'truck':'',
  'van':'',
});
const imageURLs=new Map();
export function carPhotoBody(body='',key=''){
 const b=String(body).toLowerCase(),k=String(key).toLowerCase();
 if(k==='cipherx'||b.includes('van')||b.includes('bus'))return 'van';
 if(b.includes('truck')||b.includes('pickup')||b.includes('buggy')||b.includes('rover'))return 'truck';
 if(b.includes('wagon')||b.includes('estate'))return 'wagon';
 if(b.includes('hardtop')||b.includes('sedan')||b.includes('ev'))return 'hardtop';
 if(b.includes('muscle')||b.includes('fastback')||b.includes('supercar')||b.includes('formula')||b.includes('rocket')||b.includes('prostreet'))return 'muscle';
 return 'coupe';
}
export function carPhotoUrl(body='',key=''){
 const id=carPhotoBody(body,key);
 if(imageURLs.has(id))return imageURLs.get(id);
 const raw=atob(PHOTO_DATA[id]);
 const bytes=new Uint8Array(raw.length);
 for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);
 const url=URL.createObjectURL(new Blob([bytes],{type:'image/webp'}));
 imageURLs.set(id,url);return url;
}
const bitmapCache=new Map();
export function drawPhotoCar(ctx,x,y,width,height,body='',key='',options={}){
 const id=carPhotoBody(body,key);
 let img=bitmapCache.get(id);
 if(!img){img=new Image();img.decoding='async';img.src=carPhotoUrl(body,key);bitmapCache.set(id,img);}
 if(!img.complete||!img.naturalWidth)return false;
 ctx.save();
 ctx.globalAlpha=Number.isFinite(options.opacity)?options.opacity:1;
 if(options.flip){ctx.translate(x+width,y);ctx.scale(-1,1);ctx.drawImage(img,0,0,width,height);}
 else ctx.drawImage(img,x,y,width,height);
 ctx.restore();return true;
}
export function photoElement(body='',key='',className=''){
 const img=document.createElement('img');img.src=carPhotoUrl(body,key);
 img.alt='';img.loading='lazy';img.decoding='async';img.className=className;
 return img;
}